function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // mother
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // baby
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 10 * Math.sin(t), H/2 + 60, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // pain
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 20);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(3 * t), H/2 + 40);
  ctx.stroke();

  // joy
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 20);
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(3 * t), H/2 + 40);
  ctx.stroke();

  // miracle
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 10 + 5 * Math.sin(2 * t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
